            onDragLeave$={handleDragLeave}
            onDrop$={handleDrop}
            onLayoutChange$={emitLayout}
            onHeaderCommit$={(value) => updateChromeText("header", value)}
            onFooterCommit$={(value) => updateChromeText("footer", value)}
            onJumpToNote$={jumpToNote}
          />
        </TypstWorkspace>

        <SelectionActions
          selection={
            store.userCommentPopover?.visible ||
            store.notePopover ||
            store.suggestionPopover
              ? null
              : store.selectionAction
          }
          onGetSources$={getSourcesForSelection}
          disabled={readOnly}
          onSentenceBench$={() => {
            const text = store.selectionAction?.text;
            inFlowController()?.openKind("sentence-lab", text);
            store.selectionAction = null;
          }}
          onHear$={() => {
            void readAloud();
          }}
          onThreads$={() => {
            threadInstrumentController()?.open(store.selectionAction?.text);
            store.selectionAction = null;
          }}
          onTaskDesk$={() => {
            const passage =
              store.editor && store.activeFolioId
                ? instrumentPassage(
                    store.editor.state.doc,
                    store.activeFolioId,
                    store.selectionAction ?? undefined,
                  )
                : undefined;
            openInstrumentDock("tasks", store.selectionAction?.text, passage);
            store.selectionAction = null;
          }}
          onSceneBench$={() => {
            if (!store.editor || !store.activeFolioId) return;
            const passage = instrumentPassage(
              store.editor.state.doc,
              store.activeFolioId,
              store.selectionAction ?? undefined,
            );
            openInstrumentDock("scene", passage.text, passage);
            store.selectionAction = null;
          }}
          onAddMargin$={addMarginForSelection}
          onSendToPersona$={sendSelectionToPersona}
          onClose$={() => {
            store.selectionAction = null;
          }}
        />

        {store.activeFolioId && (
          <InstrumentDock
            folioId={store.activeFolioId}
            selectedText={store.selectionAction?.text}
            disabled={readOnly}
            onAskRoom$={async (request, passage) => {
              const editor = store.editor;
              if (!editor || !store.activeFolioId)
                return {
                  ok: false,
                  message: "The manuscript is no longer available.",
                };
              const range = locateInstrumentSpan(
                editor.state.doc,
                store.activeFolioId,
                passage,
                {
                  id: "room-passage",
                  start: 0,
                  end: passage.text.length,
                  sourceOffset: passage.sourceOffset,
                  text: passage.text,
                },
              );
              if (!range)
                return {
                  ok: false,
                  message:
                    "This passage changed. Select it again before inviting an editor.",
                };
              return askInstrumentRoom(request, {
                folioId: store.activeFolioId,
                ...range,
                text: editor.state.doc.textBetween(
                  range.from,
                  range.to,
                  "\n\n",
                ),
              });
            }}
            onEntities$={() =>
              store.editor
                ? buildEntityInstrumentIndex(
                    segmentDocument(store.editor.state.doc),
                  )
                : null
            }
            onEntityJump$={(span, indexKey) => {
              const editor = store.editor;
              if (
                !editor ||
                indexKey !==
                  buildEntityInstrumentIndex(segmentDocument(editor.state.doc))
                    .key ||
                editor.state.doc.textBetween(span.from, span.to) !== span.text
              )
                return false;
              editor
                .chain()
                .setTextSelection({ from: span.from, to: span.to })
                .scrollIntoView()
                .focus()
                .run();
              return true;
            }}
            onLocate$={(span, passage) => {
              const editor = store.editor;
              if (!editor) return false;
              const range = locateInstrumentSpan(
                editor.state.doc,
                store.activeFolioId!,
                passage,
                span,
              );
              if (!range) return false;
              editor
                .chain()
                .setTextSelection(range)
                .scrollIntoView()
                .focus()
                .run();
              return true;
            }}
          />
        )}
        {!store.zenMode && (
          <div class="writing-threads-host">
            <ThreadsInstrument readOnly={readOnly} />
          </div>
        )}

        <PersonaNotePanel
          note={store.notePopover}
          onPin$={(noteId) => {
            const note = store.notePopover;
            if (note?.id === noteId && !note.pinned) {
              store.notePopover = { ...note, pinned: true };
            }
          }}
          onClose$={() => {
            threadRequest.value++;
            store.notePopover = null;
          }}
          onReply$={(noteId, text, author) => {
            window.dispatchEvent(
              new CustomEvent("twyne:persona-reply", {
                detail: { noteId, text, author },
              }),
            );
            threadDrafts[noteItemId(noteId)] = "";
            const note = store.notePopover;
            if (note?.id === noteId) {
              store.notePopover = { ...note, draft: "", error: null };
            }
          }}
          onStrike$={(noteId) => {
            dismissNote(noteId);
            if (store.notePopover?.id === noteId) {
              store.notePopover = null;
            }
          }}
        />
        <SuggestionPanel
          suggestion={store.suggestionPopover}
          stampVisible={store.stampVisible}
          onClose$={() => {
            threadRequest.value++;
            store.suggestionPopover = null;
          }}
          onStrike$={strikeSuggestion}
          onAccept$={acceptSuggestion}
        />

        <UserCommentPanel
          comment={store.userCommentPopover}
          onClose$={closeUserCommentPopover}
          onCreate$={submitWriterMargin}
          onDiscard$={discardWriterMargin}
          onSubmit$={submitUserCommentReply}
          onToggleResolved$={toggleResolveUserComment}
          onDelete$={deleteUserCommentLocal}
        />
      </div>
    );
  },
);

/* ── Persona note helpers ─────────────────────────────────────── */

/**
 * Locate `quote` inside a single text block of the document and return its
 * absolute position range. Quotes never span blocks (they are sentences),
 * so the search resets per block.
 */

function findTextRange(
  doc: any,
  quote: string,
): { from: number; to: number } | null {
  // Whitespace-tolerant: the quote may come from tag-stripped HTML where
  // inline markup left extra spaces behind.
  const escaped = quote
    .trim()
    .split(/\s+/)
    .map((word) => word.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"))
    .join("\\s+");
  if (!escaped) return null;
  const pattern = new RegExp(escaped);

  let found: { from: number; to: number } | null = null;
  doc.descendants((node: any, pos: number) => {
    if (found) return false;
    if (!node.isTextblock) return true;
    let text = "";
    const positions: number[] = [];
    node.forEach((child: any, offset: number) => {
      if (!child.isText || !child.text) return;
      for (let i = 0; i < child.text.length; i++) {
        positions.push(pos + 1 + offset + i);
      }
      text += child.text;
    });
    const match = pattern.exec(text);
    if (match) {
      found = {
        from: positions[match.index],
        to: positions[match.index + match[0].length - 1] + 1,
      };
    }
    return false;
  });
  return found;
}

function flashMarkedElement(root: HTMLElement, selector: string): void {
  const element = root.querySelector(selector) as HTMLElement | null;
  if (!element) return;
  const reduceMotion = window.matchMedia(
    "(prefers-reduced-motion: reduce)",
  ).matches;
  element.scrollIntoView({
    behavior: reduceMotion ? "auto" : "smooth",
    block: "center",
  });
  element.classList.add("is-flashing");
  setTimeout(() => element.classList.remove("is-flashing"), 1600);
}

function removeEditorMark(
  editor: Editor,
  markName: "personaNote" | "suggestion",
  id: string | null,
): void {
  const { state, view } = editor;
  const type = state.schema.marks[markName];
  if (!type) return;
  const transaction = state.tr;
  state.doc.descendants((node: any, pos: number) => {
    if (!node.isText) return true;
    for (const mark of node.marks) {
      if (mark.type === type && (id === null || mark.attrs.id === id)) {
        transaction.removeMark(pos, pos + node.nodeSize, type);
      }
    }
    return true;
  });
  if (transaction.docChanged) view.dispatch(transaction);
}

function removePersonaNote(editor: Editor, id: string | null): void {
  if (id === null) {
    removeEditorMark(editor, "personaNote", null);
    return;
  }
  removePersonaNoteMarkById(editor, id);
}

function removeAllPersonaNotes(editor: Editor): void {
  removePersonaNote(editor, null);
}

/** Find the absolute range of the suggestion mark with `id`, if present. */
function findSuggestionRange(
  editor: Editor,
  id: string,
): { from: number; to: number } | null {
  const type = editor.state.schema.marks.suggestion;
  if (!type) return null;
  let from: number | null = null;
  let to: number | null = null;
  editor.state.doc.descendants((node: any, pos: number) => {
    if (!node.isText) return true;
    if (node.marks.some((m: any) => m.type === type && m.attrs.id === id)) {
      from = from === null ? pos : Math.min(from, pos);
      to =
        to === null ? pos + node.nodeSize : Math.max(to, pos + node.nodeSize);
    }
    return true;
  });
  return from === null || to === null ? null : { from, to };
}

function removeSuggestionMark(editor: Editor, id: string | null): void {
  removeEditorMark(editor, "suggestion", id);
}

function removeAllSuggestions(editor: Editor): void {
  removeSuggestionMark(editor, null);
}

