    useVisibleTask$(
      ({ track, cleanup }) => {
        track(() => props.readOnly);
        const zen = track(() => props.zen);
        const el = root.value;
        const canvas = el?.closest<HTMLElement>(".page-canvas");
        if (!el || !canvas || zen) return;
        let frame = 0;
        let snap: LivingDeskSnapshot = livingDeskSnapshot();

        const compute = () => {
          if (document.documentElement.hasAttribute("data-flow")) {
            state.visible = false;
            return;
          }
          const ctl = livingDeskController();
          const lens = snap.lens;
          const hasFindings = snap.findings.some((f) => f.state !== "resolved");
          state.visible = !!ctl && (!props.readOnly || hasFindings);
          if (!state.visible) return;
          state.open = snap.open;
          state.height = canvas.offsetHeight;
          const est = snap.score.estimate;
          state.cap = est == null ? "" : est.toFixed(1);
          state.estimating =
            snap.score.confirmed == null || snap.score.editsSinceConfirmed > 0;
          if (!ctl) {
            state.rules = [];
            state.marks = [];
            return;
          }
          const editor = canvas.querySelector<HTMLElement>(".ProseMirror");
          const editorOffset = editor
            ? editor.getBoundingClientRect().top -
              canvas.getBoundingClientRect().top
            : 0;
          const editorHeight = editor?.scrollHeight ?? canvas.offsetHeight;
          const canvasFraction = (n: number) =>
            (editorOffset + n * editorHeight) /
            Math.max(1, canvas.offsetHeight);
          state.rules = snap.sections
            .slice(1)
            .map((s) => ctl.spineFraction(s.from))
            .filter((n): n is number => typeof n === "number")
            .map(canvasFraction);
          const marks: Mark[] = [];
          if (lens) {
            for (const f of snap.findings) {
              if (
                f.lens !== lens ||
                f.state === "resolved" ||
                f.state === "deliberate"
              )
                continue;
              const focused = snap.focusedFinding === f.id;
              for (const o of f.occurrences) {
                const top = ctl.spineFraction(o.from);
                if (top == null) continue;
                marks.push({
                  id: o.id,
                  top: canvasFraction(top),
                  strong: focused,
                  lens,
                  flagged: o.flagged,
                });
              }
            }
          }
          state.marks = marks;
        };
        const schedule = () => {
          cancelAnimationFrame(frame);
          frame = requestAnimationFrame(compute);
        };
        const onSnapshot = (event: Event) => {
          snap = (event as CustomEvent<LivingDeskSnapshot>).detail;
          schedule();
        };

        schedule();
        window.addEventListener(LIVING_DESK_EVENT, onSnapshot);
        window.addEventListener("resize", schedule);
        const observer = new ResizeObserver(schedule);
        observer.observe(canvas);
        const quietObserver = new MutationObserver(schedule);
        quietObserver.observe(document.documentElement, {
          attributes: true,
          attributeFilter: ["data-flow"],
        });
        cleanup(() => {
          cancelAnimationFrame(frame);
          window.removeEventListener(LIVING_DESK_EVENT, onSnapshot);
          window.removeEventListener("resize", schedule);
          observer.disconnect();
          quietObserver.disconnect();
        });
      },
      { strategy: "document-ready" },
    );

    return (
      <div
        ref={root}
        class="ld-spine"
        hidden={props.zen || !state.visible}
        data-ld-spine
        style={{ height: `${state.height}px` }}
      >
        <button
          type="button"
          class="ld-spine__cap"
          aria-pressed={state.open}
          aria-label="Open the piece"
          title="The piece"
          preventdefault:mousedown
          onClick$={() =>
            window.dispatchEvent(
              new CustomEvent(LIVING_DESK_TOGGLE_EVENT, {
                detail: { open: true },
              }),
            )
          }
        >
          {state.cap ? `${state.estimating ? "≈" : ""}${state.cap}` : "·"}
        </button>
        <div class="ld-spine__track" aria-hidden="true">
          {state.rules.map((top, i) => (
            <span
              key={`r${i}`}
              class="ld-spine__rule"
              style={{ top: `${top * 100}%` }}
            />
          ))}
          {state.marks.map((m) => (
            <button
              key={m.id}
              type="button"
              tabIndex={-1}
              class={[
                "ld-spine__tick",
                `ld-spine__tick--${m.lens}`,
                { "is-faint": !m.strong },
              ]}
              style={{ top: `${m.top * 100}%` }}
              aria-label="Jump to occurrence"
              preventdefault:mousedown
              onClick$={() => livingDeskController()?.jumpTo(m.id)}
            />
          ))}
        </div>
      </div>
    );
  },
);

              }}
              title="Save this tool, as you've set it up, to reuse on any passage"
            >
              Keep this tool
            </button>
          )}
          {state.keepError && (
            <p class="in-flow-card__notice" role="alert">
              {state.keepError}
            </p>
          )}
        </footer>
      </article>
    );

    return (
      <div ref={root} class="in-flow-rails" aria-live="polite">
        {state.shelf && (
          <aside class="in-flow-shelf" aria-label="Your tools">
            {/* The shelf appears once there is something on it; an empty
                placeholder would only push the writer's echoes down the
                margin. A tool card's "Keep this tool" introduces it. */}
            {state.saved.length > 0 && (
              <div class="in-flow-shelf__inner">
                <p class="in-flow-label">Your tools</p>
                <ul class="in-flow-shelf__list">
                  {state.saved.map((saved) => (
                    <li key={saved.id}>
                      <button
                        type="button"
                        class="in-flow-shelf__tool"
                        onClick$={() => inFlowController()?.openSaved(saved)}
                        title={`Use ${saved.name} on the paragraph you're in`}
                      >
                        <span>{saved.name}</span>
                        <small>{TOOL_LABELS[saved.kind]}</small>
                      </button>
                      <button
                        type="button"
                        class="in-flow-shelf__remove"
                        onClick$={() => void removeSavedTool(saved.id)}
                        aria-label={`Remove ${saved.name}`}
                      >
                        ✕
                      </button>
                    </li>
                  ))}
                </ul>
              </div>
            )}
            {state.ticks.map((top) => (
              <span
                key={`tick-${top}`}
                class="in-flow-tick"
                style={{ top: `${top}px` }}
                aria-hidden="true"
              />
            ))}
          </aside>
        )}

        {tool && state.cardTop !== null && state.mode === "rail" && (
          <>
            <span
              class="in-flow-connector"
              style={{
                top: `${state.anchorTop + Math.min(12, state.anchorHeight / 2)}px`,
              }}
              aria-hidden="true"
            />
            <div
              class="in-flow-rail"
              style={{ top: `${state.cardTop}px`, width: `${CARD_WIDTH}px` }}
            >
              {card}
            </div>
          </>
        )}

        {tool && state.cardTop !== null && state.mode === "popover" && (
          <div
            class="in-flow-popover"
            style={{
              left: `${state.popLeft}px`,
              top: `${state.popTop}px`,
              width: `${CARD_WIDTH}px`,
            }}
          >
            {card}
          </div>
        )}
      </div>
    );
  },
);

