import { chromium } from "/home/diogenes/Projects/apps/twyne/node_modules/playwright/index.mjs";
const base = "http://127.0.0.1:5174";
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const out = {};
await page.goto(`${base}/editor/`, { waitUntil: "domcontentloaded" });
// Fresh profile: file a default dossier to reach the editor.
await page.waitForURL(/dossier\/create|editor/, { timeout: 30000 });
if (page.url().includes("/dossier/create")) {
  for (let i = 0; i < 12; i++) {
    const next = page.getByRole("button", { name: "Next", exact: true });
    if (!(await next.isVisible().catch(() => false))) break;
    await next.click();
    await page.waitForTimeout(400);
  }
  await page.getByRole("button", { name: "Send to press" }).click();
  await page.getByRole("button", { name: /Continue to the editor/ }).click({ timeout: 30000 });
}
await page.waitForSelector(".ProseMirror", { timeout: 30000 });
await page.waitForTimeout(1500);
const notNow = page.getByRole("button", { name: "Not now" });
if (await notNow.isVisible().catch(() => false)) await notNow.click();
const measure = async (label) => {
  out[label] = await page.evaluate(() => {
    const header = document.querySelector(".editor-workspace-main > header");
    const controls = header?.querySelector(".flex-shrink-0");
    const title = header?.querySelector('a[href="/"]')?.parentElement;
    const refine = Array.from(header?.querySelectorAll("button") ?? []).find((b) => /dossier/i.test(b.getAttribute("aria-label") ?? ""));
    const board = document.querySelector(".editorial-overlay");
    const tr = title?.getBoundingClientRect();
    const cr = controls?.getBoundingClientRect();
    return {
      vw: innerWidth,
      headerH: Math.round(header?.getBoundingClientRect().height ?? 0),
      refineText: refine?.innerText.trim() ?? null,
      titleControlsGap: tr && cr ? Math.round(cr.left - tr.right) : null,
      boardOpen: board ? !board.classList.contains("editorial-overlay--closed") : null,
      boardW: Math.round(board?.getBoundingClientRect().width ?? 0),
      tabsH: Math.round(document.querySelector(".editorial-board-contexts")?.getBoundingClientRect().height ?? 0),
      tabsFit: Array.from(document.querySelectorAll(".editorial-board-context > strong")).every((s) => s.scrollWidth <= s.clientWidth + 1),
    };
  });
};
await measure("1440-closed");
await page.getByRole("button", { name: "Toggle the editorial board panel" }).click();
await page.waitForTimeout(800);
await measure("1440-board");
await page.setViewportSize({ width: 1024, height: 768 });
await page.waitForTimeout(800);
await measure("1024-board");
await page.screenshot({ path: "/tmp/twyne-check/1024-board.png" });
// Board persists while writing (wide layout).
await page.locator(".ProseMirror p").last().click();
await page.keyboard.type(" More words here.");
await page.waitForTimeout(600);
out.boardAfterTyping1024 = await page.evaluate(() => !document.querySelector(".editorial-overlay")?.classList.contains("editorial-overlay--closed"));
// Narrow: board covers the manuscript, so focusing the text should close it.
await page.setViewportSize({ width: 700, height: 800 });
await page.waitForTimeout(600);
if (!(await page.evaluate(() => !document.querySelector(".editorial-overlay")?.classList.contains("editorial-overlay--closed"))))
  await page.getByRole("button", { name: "Toggle the editorial board panel" }).click();
await page.waitForTimeout(600);
await measure("700-board");
await page.locator(".ProseMirror").click({ position: { x: 20, y: 20 }, force: true }).catch(() => {});
await page.waitForTimeout(600);
out.boardAfterFocus700 = await page.evaluate(() => !document.querySelector(".editorial-overlay")?.classList.contains("editorial-overlay--closed"));
await page.setViewportSize({ width: 390, height: 844 });
await page.waitForTimeout(600);
if (!(await page.evaluate(() => !document.querySelector(".editorial-overlay")?.classList.contains("editorial-overlay--closed"))))
  await page.getByRole("button", { name: "Toggle the editorial board panel" }).click().catch(() => {});
await page.waitForTimeout(800);
await measure("390-board");
await page.screenshot({ path: "/tmp/twyne-check/390-board.png" });
console.log(JSON.stringify(out, null, 1));
await browser.close();
EOF
