await measure("700-board");
await page.screenshot({ path: "/tmp/twyne-check/700-board.png" });
await page.locator(".ProseMirror").evaluate((el) => { el.focus(); el.dispatchEvent(new MouseEvent("mousedown", { bubbles: true })); el.dispatchEvent(new MouseEvent("mouseup", { bubbles: true })); el.dispatchEvent(new MouseEvent("click", { bubbles: true })); });
await page.waitForTimeout(600);
out.boardAfterFocus700 = await boardOpen();
await page.setViewportSize({ width: 390, height: 844 }); await page.waitForTimeout(600);
if (!(await boardOpen())) { await toggle.click().catch(() => {}); await page.waitForTimeout(800); }
await measure("390-board");
await page.screenshot({ path: "/tmp/twyne-check/390-board.png" });
console.log(JSON.stringify(out, null, 1));
await browser.close();
