const page = await (await browser.newContext({ viewport: { width: 1440, height: 900 } })).newPage();
await page.route(/\/api\/auth\//, (r) => r.fulfill({ contentType: "application/json", body: "null" }));
await page.route("**/__seed", (r) => r.fulfill({ contentType: "text/html", body: "<!doctype html><title>seed</title>" }));
await page.goto(`${base}/__seed`);
await page.evaluate(async (html) => {
  const db = await import(/* @vite-ignore */ "/src/utils/idb.ts");
  const now = Date.now(), id = "polish-final";
  await db.saveFoliosToIdb([{ id, name: "The bridge", type: "draft", createdAt: now, updatedAt: now }]);
  await db.saveFolioContentToIdb(id, html);
  await db.saveActiveFolioIdToIdb(id);
  await db.saveMetaToIdb("signin-toast-dismissed", true);
  localStorage.setItem("living-desk-open", "false");
  localStorage.setItem("twyne:editor:view:v1", JSON.stringify({ zenMode: false, compositorOpen: false }));
}, HTML);
await page.goto(`${base}/editor/`);
await page.locator(".ProseMirror").getByText("rents doubled", { exact: false }).waitFor({ timeout: 90000 });
await page.waitForTimeout(1500);
const out = {};
const select = (text) => page.locator(".ProseMirror").evaluate((root, text) => {
  root.focus();
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  let node, plain = "", nodes = [];
  while ((node = walker.nextNode())) { nodes.push(node); plain += node.textContent; }
  const start = plain.indexOf(text); let off = 0, began = false; const range = document.createRange();
  for (const n of nodes) { const end = off + n.length;
    if (!began && start >= off && start < end) { range.setStart(n, start - off); began = true; }
    if (began && start + text.length <= end) { range.setEnd(n, start + text.length - off); break; }
    off = end; }
  const s = getSelection(); s.removeAllRanges(); s.addRange(range);
  root.dispatchEvent(new MouseEvent("mouseup", { bubbles: true }));
}, text);
// 1. Masthead at 1440.
out.masthead1440 = await page.evaluate(() => ({ h: Math.round(document.querySelector(".editor-workspace-main > header").getBoundingClientRect().height), kicker: !!document.querySelector(".editor-workspace-main > header .dept-label")?.getClientRects().length }));
// 2. Selection toolbar.
await select(SENT);
const bar = page.getByRole("toolbar", { name: /^Actions for/ });
await bar.waitFor();
out.toolbar = await bar.evaluate((b) => ({ h: Math.round(b.getBoundingClientRect().height), labels: Array.from(b.querySelectorAll(":scope button")).map((x) => x.textContent.trim()) }));
await page.screenshot({ path: "/tmp/twyne-check/final-toolbar.png", clip: { x: 300, y: 150, width: 840, height: 420 } });
// 3. Sentence bench in the rail at 1440.
await bar.getByRole("button", { name: "Rework", exact: true }).click();
await page.locator(".sentence-bench").waitFor();
await page.waitForTimeout(800);
out.bench1440 = await page.evaluate(() => {
  const card = document.querySelector(".in-flow-card"), body = document.querySelector(".sentence-bench");
  const room = document.querySelector(".sentence-bench-room");
  const close = document.querySelector(".in-flow-card__close")?.getBoundingClientRect();
  return { host: card?.parentElement?.className, bodyH: Math.round(body.scrollHeight), roomOpen: room?.open ?? null, art: !!body.querySelector("[class*=instrument-art]"), close: close && [Math.round(close.width), Math.round(close.height)], showParagraph: !!Array.from(body.querySelectorAll("button")).find((b) => /paragraph/i.test(b.textContent)) };
});
await page.screenshot({ path: "/tmp/twyne-check/final-bench-1440.png" });
// 4. Same tool at 1280: dock, expanded because the writer asked, clear of the passage.
await page.setViewportSize({ width: 1280, height: 800 });
await page.waitForTimeout(900);
out.bench1280 = await page.evaluate((sent) => {
  const dock = document.querySelector(".in-flow-dock"), rail = document.querySelector(".in-flow-rail");
  const p = Array.from(document.querySelectorAll(".ProseMirror p")).find((x) => x.textContent.startsWith(sent.slice(0, 20)));
  const d = dock?.getBoundingClientRect(), pr = p.getBoundingClientRect();
  const sel = getSelection().rangeCount ? getSelection().getRangeAt(0).getBoundingClientRect() : null;
  const anchor = document.querySelector(".twyne-in-flow-span")?.getBoundingClientRect();
  const overlap = (a, b) => a && b && !(a.right <= b.left || b.right <= a.left || a.bottom <= b.top || b.bottom <= a.top);
  return { dock: !!dock, rail: !!rail, collapsed: dock?.classList.contains("is-collapsed"), dockRect: d && [Math.round(d.left), Math.round(d.top), Math.round(d.width), Math.round(d.height)], coversAnchor: overlap(d, anchor), vh: innerHeight };
}, SENT);
await page.screenshot({ path: "/tmp/twyne-check/final-dock-1280.png" });
// 5. Review notice when signed out (quick review answers "signed out").
await page.setViewportSize({ width: 1440, height: 900 });
await page.locator(".in-flow-card__close").click().catch(() => {});
await page.locator(".ProseMirror p").nth(2).click();
await page.keyboard.press("End");
await page.keyboard.type(" Rents doubled, landlords said, because the bridge made the far bank a short walk from the offices.", { delay: 5 });
await page.waitForTimeout(9000);
out.notice = await page.evaluate(() => { const n = document.querySelector(".live-review-status--notice"); return n ? { text: n.innerText.replace(/\s+/g, " ").trim(), h: Math.round(n.getBoundingClientRect().height) } : { none: true, label: document.querySelector(".sr-only")?.textContent }; });
console.log(JSON.stringify(out, null, 1));
await browser.close();
EOF
