1	import { describe, expect, test } from "bun:test";
2	import { EDITOR_COMMANDS } from "./editor-commands";
3	import {
4	  EDITOR_KEYBINDINGS,
5	  chordMatches,
6	  formatShortcut,
7	  keybindingList,
8	  parseShortcut,
9	  shortcutHints,
10	  shortcutPlatform,
11	} from "./keybindings";
12	
13	describe("keybinding registry", () => {
14	  test("every binding points at a real command", () => {
15	    const ids = new Set(EDITOR_COMMANDS.map((command) => command.id));
16	    for (const binding of EDITOR_KEYBINDINGS) {
17	      expect(ids.has(binding.commandId)).toBe(true);
18	    }
19	  });
20	
21	  test("shortcuts are unique except deliberate alternatives for one command", () => {
22	    const owners = new Map<string, string>();
23	    for (const binding of EDITOR_KEYBINDINGS) {
24	      const previous = owners.get(binding.shortcut);
25	      expect(previous == null || previous === binding.commandId).toBe(true);
26	      owners.set(binding.shortcut, binding.commandId);
27	    }
28	  });
29	
30	  test("platform detection handles Apple, Windows, and Linux", () => {
31	    expect(shortcutPlatform("MacIntel")).toBe("mac");
32	    expect(shortcutPlatform("iPhone")).toBe("mac");
33	    expect(shortcutPlatform("Win32")).toBe("windows");
34	    expect(shortcutPlatform("Linux x86_64")).toBe("linux");
35	  });
36	
37	  test("Mac labels use familiar symbols", () => {
38	    expect(formatShortcut("Mod-b", "mac")).toBe("⌘B");
39	    expect(formatShortcut("Mod-Shift-z", "mac")).toBe("⌘⇧Z");
40	    expect(formatShortcut("Mod-Enter", "mac")).toBe("⌘↩");
41	    expect(formatShortcut("Shift-Tab", "mac")).toBe("⇧⇥");
42	  });
43	
44	  test("Windows and Linux labels use named modifiers", () => {
45	    expect(formatShortcut("Mod-b", "windows")).toBe("Ctrl+B");
46	    expect(formatShortcut("Mod-Shift-z", "linux")).toBe("Ctrl+Shift+Z");
47	    expect(formatShortcut("Alt-ArrowDown", "windows")).toBe("Alt+↓");
48	  });
49	
50	  test("parser separates modifiers from the key", () => {
51	    expect(parseShortcut("Mod-Alt-1")).toEqual({
52	      modifiers: ["Mod", "Alt"],
53	      key: "1",
54	    });
55	  });
