import { chromium } from "/home/diogenes/Projects/apps/twyne/node_modules/playwright/index.mjs";
const port = process.argv[2];
const base = `http://127.0.0.1:${port}`;
const browser = await chromium.launch();
const runs = [];
for (let r = 0; r < 3; r++) {
  const page = await (await browser.newContext({ viewport: { width: 1280, height: 900 } })).newPage();
  await page.goto(`${base}/`);
  await page.evaluate(async () => {
    const db = await new Promise((resolve, reject) => {
      const req = indexedDB.open("twyne", 2);
      req.onupgradeneeded = () => { const d = req.result; for (const [n, k] of [["folios","id"],["folio-content","folioId"],["brief","folioId"],["comments","id"],["personas","id"],["meta","key"],["ai-settings","key"],["lix-blob","key"],["voice-notes","id"]]) if (!d.objectStoreNames.contains(n)) d.createObjectStore(n, { keyPath: k }); };
      req.onsuccess = () => resolve(req.result); req.onerror = () => reject(req.error);
    });
    const now = Date.now(), id = "e2e-drag-selection";
    await new Promise((resolve, reject) => {
      const t = db.transaction(["folios", "folio-content", "meta"], "readwrite");
      t.objectStore("folios").put({ id, name: "Drag fixture", type: "draft", createdAt: now, updatedAt: now, layout: { pagination: "paginated" } });
      t.objectStore("folio-content").put({ folioId: id, html: "<p>Alpha paragraph.</p><p>Beta paragraph.</p>", updatedAt: now });
      t.objectStore("meta").put({ key: "active-folio-id", value: id, updatedAt: now });
      t.oncomplete = () => resolve(); t.onerror = () => reject(t.error);
    });
  });
  await page.goto(`${base}/editor/`);
  await page.locator(".ProseMirror").waitFor({ timeout: 30000 });
  await page.waitForTimeout(1500);
  const para = page.locator(".ProseMirror > p").nth(1);
  await para.click();
  await page.keyboard.press("Home");
  await page.keyboard.press("Shift+End");
  const snap = async (label) => ({ label, ...(await page.evaluate(() => {
    const s = getSelection();
    const a = document.activeElement;
    return { sel: s?.toString() ?? "", collapsed: s?.isCollapsed, active: a?.className?.toString().slice(0, 40) || a?.tagName, toolbar: !!document.querySelector(".selection-actions"), toolbarFocus: !!document.activeElement?.closest?.(".selection-actions") };
  })) });
  const steps = [await snap("after shift+end")];
  await page.waitForTimeout(150); steps.push(await snap("+150ms"));
  await page.waitForTimeout(600); steps.push(await snap("+750ms"));
  await page.waitForTimeout(1500); steps.push(await snap("+2250ms"));
  runs.push(steps);
